'''
Combination parsing and comparison logic for Dou Dizhu.
'''

from dataclasses import dataclass
from enum import Enum
from typing import List, Optional
from collections import Counter

from cards import Card, sort_cards


class CombinationType(str, Enum):
    INVALID = "invalid"
    SINGLE = "single"
    PAIR = "pair"
    TRIPLE = "triple"
    STRAIGHT = "straight"
    PAIR_STRAIGHT = "pair_straight"
    TRIPLE_STRAIGHT = "triple_straight"
    BOMB = "bomb"
    ROCKET = "rocket"
    TRIPLE_ONE = "triple_one"
    TRIPLE_PAIR = "triple_pair"


@dataclass
class Combination:
    type: CombinationType
    cards: List[Card]
    primary_value: int
    length: int = 1

    def description(self) -> str:
        return self.type.value.replace("_", " ").title()


def _is_consecutive(values: List[int]) -> bool:
    return all(values[i] + 1 == values[i + 1] for i in range(len(values) - 1))


def analyze_cards(cards: List[Card]) -> Optional[Combination]:
    if not cards:
        return None

    cards = sort_cards(cards)
    values = [c.value for c in cards]
    count = Counter(values)
    unique = sorted(count.keys())
    n = len(cards)

    if n == 1:
        return Combination(CombinationType.SINGLE, cards, values[0], 1)

    if n == 2:
        if set(values) == {16, 17}:
            return Combination(CombinationType.ROCKET, cards, 17, 1)
        if len(count) == 1:
            return Combination(CombinationType.PAIR, cards, values[0], 1)
        return None

    if n == 3:
        if len(count) == 1:
            return Combination(CombinationType.TRIPLE, cards, values[0], 1)
        return None

    if n == 4:
        if len(count) == 1:
            return Combination(CombinationType.BOMB, cards, values[0], 1)
        if sorted(count.values()) == [1, 3]:
            triple_val = max(count, key=lambda k: count[k])
            return Combination(CombinationType.TRIPLE_ONE, cards, triple_val, 1)
        return None

    if n == 5:
        if len(count) == 2 and sorted(count.values()) == [2, 3]:
            triple_val = max(count, key=lambda k: count[k])
            return Combination(CombinationType.TRIPLE_PAIR, cards, triple_val, 1)
        if all(v < 15 for v in unique) and len(count) == 5 and _is_consecutive(unique):
            return Combination(CombinationType.STRAIGHT, cards, max(unique), 5)
        return None

    if all(v < 15 for v in unique) and len(count) == n and _is_consecutive(unique):
        return Combination(CombinationType.STRAIGHT, cards, max(unique), n)

    if n % 2 == 0 and all(v < 15 for v in unique):
        if all(c == 2 for c in count.values()) and len(count) == n // 2 and _is_consecutive(unique):
            return Combination(CombinationType.PAIR_STRAIGHT, cards, max(unique), n // 2)

    if n % 3 == 0 and all(v < 15 for v in unique):
        if all(c == 3 for c in count.values()) and len(count) == n // 3 and _is_consecutive(unique):
            return Combination(CombinationType.TRIPLE_STRAIGHT, cards, max(unique), n // 3)

    return None


def can_beat(new_combo: Combination, last_combo: Optional[Combination]) -> bool:
    if last_combo is None:
        return True

    if new_combo.type == CombinationType.ROCKET:
        return True

    if last_combo.type == CombinationType.ROCKET:
        return False

    if new_combo.type == CombinationType.BOMB and last_combo.type != CombinationType.BOMB:
        return True

    if new_combo.type == CombinationType.BOMB and last_combo.type == CombinationType.BOMB:
        return new_combo.primary_value > last_combo.primary_value

    if last_combo.type == CombinationType.BOMB and new_combo.type != CombinationType.BOMB:
        return False

    if new_combo.type != last_combo.type:
        return False

    if new_combo.length != last_combo.length:
        return False

    return new_combo.primary_value > last_combo.primary_value

'''
Simple AI bidding and playing logic.
'''

from typing import List, Optional

from cards import Card, sort_cards
from combination import analyze_cards, can_beat, Combination, CombinationType
from game_state import GameState


def choose_bid(state: GameState, player_index: int) -> int:
    hand = state.players[player_index]
    strength = sum(card.value for card in hand)
    if any(card.rank in ("SJ", "BJ") for card in hand):
        strength += 20
    if any(card.value >= 15 for card in hand):
        strength += 10
    if strength > 190:
        return 3
    if strength > 175:
        return 2
    if strength > 160:
        return 1
    return 0


def _group_by_value(cards: List[Card]):
    groups = {}
    for c in cards:
        groups.setdefault(c.value, []).append(c)
    return groups


def _find_play_from_candidates(candidates: List[List[Card]], last_combo: Optional[Combination]):
    valid = []
    for c in candidates:
        combo = analyze_cards(c)
        if combo and can_beat(combo, last_combo):
            valid.append((combo, c))
    if not valid:
        return None
    valid.sort(key=lambda x: (x[0].type.value, x[0].primary_value, len(x[1])))
    return valid[0][1]


def choose_play(state: GameState, player_index: int) -> Optional[List[Card]]:
    hand = sort_cards(state.players[player_index])
    last_combo = state.last_combo

    if last_combo is None:
        singles = [[c] for c in hand]
        play = _find_play_from_candidates(singles, None)
        if play:
            return play
        return [hand[0]] if hand else None

    groups = _group_by_value(hand)
    candidates: List[List[Card]] = []

    if last_combo.type == CombinationType.SINGLE:
        for c in hand:
            candidates.append([c])

    elif last_combo.type == CombinationType.PAIR:
        for v, g in groups.items():
            if len(g) >= 2:
                candidates.append(g[:2])

    elif last_combo.type == CombinationType.TRIPLE:
        for v, g in groups.items():
            if len(g) >= 3:
                candidates.append(g[:3])

    elif last_combo.type == CombinationType.BOMB:
        for v, g in groups.items():
            if len(g) >= 4:
                candidates.append(g[:4])

    if last_combo.type not in (CombinationType.ROCKET,):
        if len(groups.get(16, [])) >= 1 and len(groups.get(17, [])) >= 1:
            candidates.append([groups[16][0], groups[17][0]])

    for v, g in groups.items():
        if len(g) >= 4:
            candidates.append(g[:4])

    play = _find_play_from_candidates(candidates, last_combo)
    if play:
        return play

    return None

'''
Tkinter GUI application for Dou Dizhu.
'''

import tkinter as tk
from tkinter import messagebox

from cards import Card
from game_state import GameState
from ai_player import choose_bid, choose_play


class DouDizhuApp:
    def __init__(self, root):
        self.root = root
        self.root.title("Dou Dizhu")
        self.root.geometry("1100x700")

        self.state = GameState()
        self.selected_indices = set()
        self.player_modes = ["human", "ai", "ai"]

        self._build_ui()
        self.new_game()

    def _build_ui(self):
        self.info_label = tk.Label(self.root, text="", font=("Arial", 14))
        self.info_label.pack(pady=8)

        self.table_label = tk.Label(self.root, text="", font=("Arial", 12), fg="blue")
        self.table_label.pack(pady=4)

        self.landlord_label = tk.Label(self.root, text="", font=("Arial", 12), fg="purple")
        self.landlord_label.pack(pady=4)

        self.hand_frame = tk.Frame(self.root)
        self.hand_frame.pack(side=tk.BOTTOM, fill=tk.X, pady=15)

        self.center_frame = tk.Frame(self.root)
        self.center_frame.pack(side=tk.BOTTOM, pady=8)

        self.bid_frame = tk.Frame(self.root)
        self.bid_frame.pack(side=tk.TOP, pady=10)

        self.buttons = []
        for i in range(3):
            btn = tk.Button(self.bid_frame, text=f"Bid {i}", width=10,
                            command=lambda v=i: self.human_bid(v))
            btn.grid(row=0, column=i, padx=5)
            self.buttons.append(btn)

        self.pass_button = tk.Button(self.center_frame, text="Pass", width=12, command=self.human_pass)
        self.pass_button.grid(row=0, column=0, padx=5)

        self.play_button = tk.Button(self.center_frame, text="Play Selected", width=15, command=self.human_play)
        self.play_button.grid(row=0, column=1, padx=5)

        self.new_button = tk.Button(self.center_frame, text="New Game", width=12, command=self.new_game)
        self.new_button.grid(row=0, column=2, padx=5)

        self.cards_canvas = tk.Frame(self.root)
        self.cards_canvas.pack(fill=tk.BOTH, expand=True, pady=10)

    def new_game(self):
        self.state.start_new_game()
        self.selected_indices.clear()
        self._refresh()
        self.root.after(500, self._auto_bidding_loop)

    def _auto_bidding_loop(self):
        if not self.state.bidding_phase:
            self._refresh()
            self._maybe_ai_turn()
            return

        if self.state.highest_bidder is None:
            current = self.state.bid_rounds_done % 3
        else:
            current = self.state.bid_rounds_done % 3

        if self.player_modes[current] == "human":
            self._refresh()
            return

        bid = choose_bid(self.state, current)
        self.state.bid(current, bid)
        self._refresh()
        if self.state.bidding_phase:
            self.root.after(700, self._auto_bidding_loop)
        else:
            self._maybe_ai_turn()

    def human_bid(self, bid_value):
        if not self.state.bidding_phase:
            return
        if self.player_modes[self.state.bid_rounds_done % 3] != "human":
            return
        self.state.bid(self.state.bid_rounds_done % 3, bid_value)
        self._refresh()
        if self.state.bidding_phase:
            self.root.after(200, self._auto_bidding_loop)
        else:
            self._maybe_ai_turn()

    def human_pass(self):
        if self.state.bidding_phase or self.state.winner is not None:
            return
        if self.state.current_turn != 0:
            return
        if self.state.pass_turn(0):
            self.selected_indices.clear()
            self._refresh()
            self._maybe_ai_turn()

    def human_play(self):
        if self.state.bidding_phase or self.state.winner is not None:
            return
        if self.state.current_turn != 0:
            return
        hand = self.state.players[0]
        cards = [hand[i] for i in sorted(self.selected_indices)]
        if self.state.play_cards(0, cards):
            self.selected_indices.clear()
            self._refresh()
            self._maybe_ai_turn()
        else:
            messagebox.showerror("Invalid Move", "Selected cards do not form a valid playable combination.")

    def _maybe_ai_turn(self):
        if self.state.bidding_phase or self.state.winner is not None:
            self._refresh()
            return

        current = self.state.current_turn
        if self.player_modes[current] == "human":
            self._refresh()
            return

        self.root.after(700, self._ai_take_turn)

    def _ai_take_turn(self):
        if self.state.winner is not None or self.state.bidding_phase:
            self._refresh()
            return

        current = self.state.current_turn
        if self.player_modes[current] != "ai":
            self._refresh()
            return

        play = choose_play(self.state, current)
        if play is None:
            self.state.pass_turn(current)
        else:
            self.state.play_cards(current, play)

        self._refresh()
        if self.state.winner is None:
            self._maybe_ai_turn()

    def _card_button_command(self, idx):
        if idx in self.selected_indices:
            self.selected_indices.remove(idx)
        else:
            self.selected_indices.add(idx)
        self._refresh()

    def _refresh(self):
        self._render_info()
        self._render_table()
        self._render_hand()
        self._render_buttons_state()

    def _render_info(self):
        if self.state.winner is not None:
            winner_text = "Landlord" if self.state.winner == self.state.landlord_index else "Farmers"
            self.info_label.config(text=f"Game Over: Player {self.state.winner + 1} wins! ({winner_text})")
            return

        if self.state.bidding_phase:
            turn = self.state.bid_rounds_done % 3
            self.info_label.config(text=f"Bidding phase. Player {turn + 1}'s turn.")
        else:
            self.info_label.config(text=f"Turn: Player {self.state.current_turn + 1}")

        if self.state.landlord_index is None:
            self.landlord_label.config(text="Landlord: not decided yet")
        else:
            self.landlord_label.config(text=f"Landlord: Player {self.state.landlord_index + 1}")

    def _render_table(self):
        if self.state.last_combo is None:
            self.table_label.config(text="Last play: none")
        else:
            desc = self.state.last_combo.description()
            cards = " ".join(card.label() for card in self.state.last_combo.cards)
            self.table_label.config(text=f"Last play: {desc} | {cards}")

    def _render_hand(self):
        for widget in self.cards_canvas.winfo_children():
            widget.destroy()

        if not self.state.players:
            return

        hand = self.state.players[0]
        for idx, card in enumerate(hand):
            selected = idx in self.selected_indices
            txt = card.label()
            if selected:
                txt = f"[{txt}]"
            btn = tk.Button(self.cards_canvas, text=txt, width=6,
                            command=lambda i=idx: self._card_button_command(i),
                            bg="#ffd966" if selected else "white")
            btn.pack(side=tk.LEFT, padx=2)

    def _render_buttons_state(self):
        bidding = self.state.bidding_phase
        turn = self.state.bid_rounds_done % 3 if bidding else self.state.current_turn
        human_turn = (turn == 0 and self.player_modes[0] == "human")

        for btn in self.buttons:
            btn.config(state=tk.NORMAL if bidding and human_turn else tk.DISABLED)

        if self.state.bidding_phase:
            self.pass_button.config(state=tk.DISABLED)
            self.play_button.config(state=tk.DISABLED)
        else:
            self.pass_button.config(state=tk.NORMAL if human_turn and self.state.last_combo is not None else tk.DISABLED)
            self.play_button.config(state=tk.NORMAL if human_turn else tk.DISABLED)


def run_app():
    root = tk.Tk()
    app = DouDizhuApp(root)
    root.mainloop()

