'''
sudoku_utils.py

Utility functions for Sudoku:
- validation
- solving
- generation
- completion checking
'''

import copy
import random


def is_valid_move(board, row, col, num):
    '''Return True if placing num at board[row][col] is valid.'''
    for c in range(9):
        if c != col and board[row][c] == num:
            return False

    for r in range(9):
        if r != row and board[r][col] == num:
            return False

    start_row = (row // 3) * 3
    start_col = (col // 3) * 3

    for r in range(start_row, start_row + 3):
        for c in range(start_col, start_col + 3):
            if (r != row or c != col) and board[r][c] == num:
                return False

    return True


def find_empty(board):
    '''Find the next empty cell (value 0). Return (row, col) or None.'''
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                return r, c
    return None


def solve_board(board):
    '''Solve the Sudoku board in-place using backtracking.'''
    empty = find_empty(board)
    if empty is None:
        return True

    row, col = empty
    nums = list(range(1, 10))
    random.shuffle(nums)

    for num in nums:
        if is_valid_move(board, row, col, num):
            board[row][col] = num
            if solve_board(board):
                return True
            board[row][col] = 0

    return False


def generate_full_board():
    '''Generate a complete valid Sudoku solution.'''
    board = [[0 for _ in range(9)] for _ in range(9)]
    solve_board(board)
    return board


def generate_puzzle(empty_cells=45):
    '''
    Generate a Sudoku puzzle and its solution.

    empty_cells controls difficulty:
    - more empty cells -> harder puzzle
    '''
    solution = generate_full_board()
    puzzle = copy.deepcopy(solution)

    cells = [(r, c) for r in range(9) for c in range(9)]
    random.shuffle(cells)

    removed = 0
    for r, c in cells:
        if removed >= empty_cells:
            break
        puzzle[r][c] = 0
        removed += 1

    return puzzle, solution


def board_is_complete(board):
    '''Check whether a board has no empty cells and is valid.'''
    for r in range(9):
        for c in range(9):
            val = board[r][c]
            if val == 0:
                return False
            board[r][c] = 0
            valid = is_valid_move(board, r, c, val)
            board[r][c] = val
            if not valid:
                return False
    return True

